import logging

import httpx
from fastapi import FastAPI, HTTPException, Request
from fastapi.exception_handlers import http_exception_handler, request_validation_exception_handler
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse, Response
from fastapi.templating import Jinja2Templates
from sqlalchemy.exc import DBAPIError
from starlette.exceptions import HTTPException as StarletteHTTPException

log = logging.getLogger(__name__)
templates = Jinja2Templates(directory="templates")

COPY = {
    404: ("Page not found", "That page does not exist or has moved."),
    410: ("Page removed", "This page has been permanently removed."),
    500: ("Something went wrong", "We hit a problem on our side. Please try again shortly."),
    503: ("Temporarily unavailable", "The service is busy or down for maintenance. Please try again shortly."),
}


def wants_html(request: Request) -> bool:
    return not request.url.path.startswith("/api/")


def error_page(request: Request, status: int, headers: dict[str, str] | None = None) -> Response:
    title, message = COPY[status]
    home = (request.scope.get("root_path") or "") + "/"  # mount root, respects --root-path
    context = {"title": title, "message": message, "home": home}
    return templates.TemplateResponse(request, "error.html", context, status_code=status, headers=headers)


def install_error_handlers(app: FastAPI) -> None:
    @app.exception_handler(StarletteHTTPException)
    async def http_error(request: Request, exc: StarletteHTTPException) -> Response:
        if wants_html(request) and exc.status_code in COPY:
            return error_page(request, exc.status_code, exc.headers)
        return await http_exception_handler(request, exc)

    @app.exception_handler(RequestValidationError)
    async def validation_error(request: Request, exc: RequestValidationError) -> Response:
        if any(e["loc"] and e["loc"][0] == "path" for e in exc.errors()):  # unknown route param -> 404 (RTE-006)
            if wants_html(request):
                return error_page(request, 404)
            return JSONResponse({"detail": "Not Found"}, status_code=404)
        return await request_validation_exception_handler(request, exc)

    async def dependency_down(request: Request, exc: Exception) -> Response:  # RTE-007: 503, never 404 or 200
        log.warning("dependency failure on %s", request.url.path, exc_info=exc)
        if wants_html(request):
            return error_page(request, 503, {"Retry-After": "30"})
        return JSONResponse({"status": "unavailable"}, status_code=503)

    for exc_type in (DBAPIError, ConnectionError, TimeoutError, httpx.TransportError):
        app.add_exception_handler(exc_type, dependency_down)

    @app.exception_handler(Exception)
    async def crash(request: Request, exc: Exception) -> Response:
        log.exception("unhandled error on %s", request.url.path)
        if wants_html(request):
            return error_page(request, 500)
        return JSONResponse({"detail": "Internal Server Error"}, status_code=500)
