import os
from urllib.parse import urlsplit

from starlette.datastructures import Headers
from starlette.responses import PlainTextResponse
from starlette.types import ASGIApp, Receive, Scope, Send

SAFE_METHODS = {"GET", "HEAD", "OPTIONS"}
parts = urlsplit(os.environ.get("SITE_URL", "https://example.com"))
ALLOWED_ORIGINS = {f"{parts.scheme}://{parts.netloc}"}


class OriginCheckMiddleware:
    """SEC-024: reject cross-site non-GET requests (a browser always sends Origin on a cross-site POST)."""

    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] == "http" and scope["method"] not in SAFE_METHODS:
            headers = Headers(scope=scope)
            origin, site = headers.get("origin"), headers.get("sec-fetch-site")
            if origin is not None:
                allowed = origin in ALLOWED_ORIGINS
            elif site is not None:
                allowed = site in ("same-origin", "none")
            else:
                allowed = True  # no browser headers at all: curl or a webhook sender, no ambient cookies to abuse
            if not allowed:
                await PlainTextResponse("Forbidden", status_code=403)(scope, receive, send)
                return
        await self.app(scope, receive, send)
