import logging
import os
import re
from typing import Annotated

import httpx
from fastapi import APIRouter, FastAPI, Form, Request
from fastapi.responses import PlainTextResponse, RedirectResponse, Response
from fastapi.templating import Jinja2Templates
from slowapi import Limiter
from slowapi.errors import RateLimitExceeded
from slowapi.util import get_remote_address

log = logging.getLogger(__name__)
router = APIRouter()
templates = Jinja2Templates(directory="templates")
limiter = Limiter(key_func=get_remote_address)
WEBHOOK_URL = os.environ["FORM_WEBHOOK_URL"]  # the delivery target; never exposed to the browser
EMAIL = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def install(app: FastAPI) -> None:
    app.state.limiter = limiter

    async def too_many(request: Request, exc: Exception) -> Response:
        return PlainTextResponse("Too many requests. Please try again later.", 429, headers={"Retry-After": "600"})

    app.add_exception_handler(RateLimitExceeded, too_many)  # SEC-054
    app.include_router(router)


def page(request: Request, status: int = 200, error: str | None = None, values=None, errors=None) -> Response:
    context = {"error": error, "values": values or {}, "errors": errors or {}}
    return templates.TemplateResponse(request, "contact.html", context, status_code=status)


@router.get("/contact", include_in_schema=False)
async def contact_form(request: Request) -> Response:
    return page(request)


@router.post("/contact", include_in_schema=False)
@limiter.limit("5/10 minutes")
async def contact_submit(
    request: Request,
    name: Annotated[str, Form()] = "",
    email: Annotated[str, Form()] = "",
    message: Annotated[str, Form()] = "",
    website: Annotated[str, Form()] = "",  # honeypot (SEC-055)
) -> Response:
    if website:  # a bot filled the hidden field: look successful, do nothing
        return RedirectResponse("/contact/thanks", status_code=303)
    values = {"name": name.strip(), "email": email.strip(), "message": message.strip()}
    errors = {}
    if not 1 <= len(values["name"]) <= 100:
        errors["name"] = "Enter your name (100 characters at most)."
    if len(values["email"]) > 254 or not EMAIL.match(values["email"]):
        errors["email"] = "Enter a valid email address."
    if not 1 <= len(values["message"]) <= 5000:
        errors["message"] = "Enter a message (5000 characters at most)."
    if errors:
        return page(request, 400, values=values, errors=errors)
    try:
        # DELIVERY: the one block a project replaces (email API, CRM call, database insert).
        async with httpx.AsyncClient(timeout=8.0) as client:
            res = await client.post(WEBHOOK_URL, json=values)
            res.raise_for_status()
    except httpx.HTTPError:
        log.exception("contact delivery failed")
        return page(request, 502, "We could not send your message. Please try again shortly.", values)  # RES-008
    return RedirectResponse("/contact/thanks", status_code=303)


@router.get("/contact/thanks", include_in_schema=False)
async def contact_thanks(request: Request) -> Response:
    # IDX-016: the confirmation page stays out of the index.
    return templates.TemplateResponse(request, "contact_thanks.html", {}, headers={"X-Robots-Tag": "noindex"})
