FastAPI. Mode comes from DEPLOY_ENV only ("production" is the one production value), read from the process environment on every request (nothing is inlined at build). Set SITE_URL=https://example.com. Non-production: robots.txt is Disallow: /, /sitemap.xml answers 404, and every response (static files included) carries X-Robots-Tag: noindex, nofollow. FastAPI has no sitemap helper: the code below writes escaped, unique, absolute URLs and splits into a sitemap index above 50,000 URLs.
### file: app/seo.py
import os
from urllib.parse import quote
from xml.sax.saxutils import escape

from fastapi import APIRouter, HTTPException
from fastapi.responses import Response
from starlette.datastructures import MutableHeaders
from starlette.types import ASGIApp, Message, Receive, Scope, Send

router = APIRouter()
MAX_URLS = 50_000  # per sitemap file (IDX-002)
NS = "http://www.sitemaps.org/schemas/sitemap/0.9"


def is_production() -> bool:
    return os.environ.get("DEPLOY_ENV") == "production"


def site_url() -> str:
    return os.environ.get("SITE_URL", "https://example.com").rstrip("/")


async def indexable_paths() -> list[str]:
    # Canonical paths of indexable public pages only (200, canonical, not noindex); add DB/CMS pages here.
    return ["/", "/contact"]


def absolute(path: str) -> str:
    return escape(site_url() + quote(path, safe="/"))


def xml(body: str) -> Response:
    return Response('<?xml version="1.0" encoding="UTF-8"?>\n' + body, media_type="application/xml")


async def parts() -> list[list[str]]:
    paths = list(dict.fromkeys(await indexable_paths()))  # unique, order kept
    return [paths[i : i + MAX_URLS] for i in range(0, len(paths), MAX_URLS)] or [[]]


@router.get("/robots.txt", include_in_schema=False)
async def robots() -> Response:
    if is_production():
        # Only app/API paths are disallowed, never CSS/JS/images (IDX-004).
        lines = ["User-agent: *", "Allow: /", "Disallow: /api/", f"Sitemap: {site_url()}/sitemap.xml"]
    else:
        lines = ["User-agent: *", "Disallow: /"]  # no Sitemap line
    return Response("\n".join(lines) + "\n", media_type="text/plain")


@router.get("/sitemap.xml", include_in_schema=False)
async def sitemap() -> Response:
    if not is_production():
        raise HTTPException(status_code=404)
    chunks = await parts()
    if len(chunks) == 1:
        rows = "".join(f"<url><loc>{absolute(p)}</loc></url>" for p in chunks[0])
        return xml(f'<urlset xmlns="{NS}">{rows}</urlset>')
    rows = "".join(f"<sitemap><loc>{absolute(f'/sitemap-{n}.xml')}</loc></sitemap>" for n in range(1, len(chunks) + 1))
    return xml(f'<sitemapindex xmlns="{NS}">{rows}</sitemapindex>')


@router.get("/sitemap-{n}.xml", include_in_schema=False)
async def sitemap_part(n: int) -> Response:
    chunks = await parts()
    if not is_production() or len(chunks) == 1 or not 1 <= n <= len(chunks):
        raise HTTPException(status_code=404)
    rows = "".join(f"<url><loc>{absolute(p)}</loc></url>" for p in chunks[n - 1])
    return xml(f'<urlset xmlns="{NS}">{rows}</urlset>')


class NoindexOutsideProduction:
    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http" or is_production():
            await self.app(scope, receive, send)
            return

        async def send_noindex(message: Message) -> None:
            if message["type"] == "http.response.start":
                MutableHeaders(scope=message)["X-Robots-Tag"] = "noindex, nofollow"  # IDX-005
            await send(message)

        await self.app(scope, receive, send_noindex)
